package com.kmbeast.controller;import com.kmbeast.annotation.AdminOnly;import com.kmbeast.pojo.api.R;import com.kmbeast.pojo.dto.*;import com.kmbeast.pojo.entity.OrdersRefundReply;import com.kmbeast.service.RefundService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/orders-refund-reply") @RequiredArgsConstructor public class OrdersRefundReplyController{private final RefundService service;@PostMapping("/refund")public R<Void> refund(@Valid @RequestBody RefundDTO d){return service.refund(d);}@AdminOnly @PutMapping("/audit")public R<Void> audit(@Valid @RequestBody RefundAuditDTO d){return service.audit(d);}@PostMapping("/list")public R<List<OrdersRefundReply>> list(@RequestBody(required=false) Map<String,Integer>d){return service.list(d==null?null:d.get("ordersId"));}}
